      --accent: #9b3f2f;
      --accent-light: #ead8ce;
      --shadow: rgba(48, 41, 31, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: 2rem 1rem 4rem;
      background: var(--background);
      color: var(--text);
      font-family: Georgia, "Times New Roman", serif;
      line-height: 1.6;
    }

    main {
      width: min(1100px, 100%);
      margin: 0 auto;
    }

    header {
      margin-bottom: 2rem;
      padding: 2rem;
      border: 2px solid var(--accent);
      border-radius: 1rem;
      background: var(--surface);
      text-align: center;
      box-shadow: 0 0.75rem 2rem var(--shadow);
    }

    h1 {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: clamp(2rem, 5vw, 3.5rem);
      line-height: 1.1;
    }

    .introduction {
      max-width: 45rem;
      margin: 1rem auto;
    }

    .keywords {
      margin-bottom: 0;
      color: #665c4e;
      font-size: 0.95rem;
    }

    .limericks {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1.25rem;
      padding-left: 2.5rem;
    }

    .limericks li {
      margin-bottom: 0.5rem;
      padding: 1.25rem 1.4rem;
      border-left: 0.35rem solid var(--accent);
      border-radius: 0.65rem;
      background: var(--surface);
      box-shadow: 0 0.4rem 1.1rem var(--shadow);
      break-inside: avoid;
    }

    .limericks li::marker {
      color: var(--accent);
      font-weight: bold;
    }

    .limericks p {
      margin: 0;
      font-size: 1.08rem;
    }

    footer {
      margin-top: 2rem;
      color: #665c4e;
      font-size: 0.9rem;
      text-align: center;
    }

    @media (max-width: 720px) {
      body {
        padding-top: 1rem;
      }

      header {
        padding: 1.4rem;
      }

      .limericks {
        grid-template-columns: 1fr;
        padding-left: 2rem;
      }
    }

    @media print {
      body {
        padding: 0;
        background: white;
      }

      header,
      .limericks li {
        box-shadow: none;
      }

      .limericks {
        display: block;
      }

      .limericks li {
        margin-bottom: 1rem;
      }
    }
  </style>
</head>

